CREATE TABLE IF NOT EXISTS shipments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,carrier VARCHAR(120) NULL,service VARCHAR(120) NULL,tracking_number VARCHAR(190) NULL,status ENUM('pending','packed','dispatched','in_transit','out_for_delivery','delivered','returned','exception') NOT NULL DEFAULT 'pending',estimated_delivery_date DATE NULL,shipped_at TIMESTAMP NULL,delivered_at TIMESTAMP NULL,notes TEXT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY shipment_tracking(tracking_number),KEY shipment_order(order_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS shipment_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,shipment_id BIGINT UNSIGNED NOT NULL,status VARCHAR(60) NOT NULL,location VARCHAR(190) NULL,message VARCHAR(500) NULL,event_at TIMESTAMP NOT NULL,created_at TIMESTAMP NULL,KEY shipment_event_lookup(shipment_id,event_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
